const EventList = dynamic(import('./EventList'), {
  loading: () => <ReactLoader />,
});
const SessionDetails = dynamic(import('components/features/sessions/SessionDetails'));
const ResizePanel = dynamic(
  () => import('components/shared/ResizePanel/ResizePanel'),
  { ssr: false }
);

const defaultOrderBy = [
  {
    id: 'city',
    desc: true,
  }
]

const EventDetailsAndVideo = () => {
  const fullScreenContainerRef = useRef();
  const dispatch = useDispatch();
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const {
    urlReducer: urlQuery,
    appFilter,
  } = useSelector((state) => state);
  const [orderBy, setOrderBy] = useState([]);
  const [isMounted, componentMountToggler] = useState(false)
  const { appId: appid } = urlQuery;
  const {
    event: { segment: eventSegment },
    dateSegment,
    fetchProperty,
  } = appFilter;
  const resizeWidth = appFilter?.eventDetailSize;
  const eventProperties = fetchProperty.event_custom_property.data || [];
  const userProperties = fetchProperty.user_custom_property.data || [];
  const { eventpage, sessionid, parentType, autoplay, eventid, starttime, appId } = urlQuery;
  const pageNumber = Number(eventpage) || 1;
  const appIdCopy = appId || appid
  let eventsListReqBody = ''
  try {
    eventsListReqBody = JSON.parse(localStorage.getItem('eventsListReqBody'))
  } catch (err) {
    // silent fail
  }
  const isWebApp = useIsAppType( 'web' );

  const reqBody = useMemo(
    () => ({
      appid: appIdCopy,
      filters: [...eventSegment],
      date_range: { ...dateSegment, table: parentType === 'nocodeEventsList' ? 'no_code_event' : 'event' },
      page: pageNumber || 1,
      ...( ( orderBy?.length || eventsListReqBody ) && { orderBy: orderBy?.length ? [{
        sortName: orderBy[0]?.id,
        sortOrder: orderBy[0]?.desc ? 'desc' : 'asc',
        ...orderBy[0].isCustomUserProperty && { isCustomUserProperty: orderBy[0].isCustomUserProperty },
        ...orderBy[0].isCustomEventProperty && { isCustomEventProperty: orderBy[0].isCustomEventProperty }
      }] : eventsListReqBody?.orderBy  }),
      webApp: isWebApp,
    }), [ appIdCopy, dateSegment, eventSegment, orderBy, pageNumber, parentType, isWebApp, eventsListReqBody]
  );
  useEffect(() => {
    try {
      localStorage.setItem('eventsListReqBody', JSON.stringify(reqBody))
    } catch (err) {
      // silent fail
    }
  }, [reqBody])

  const { data: eventsListData, refetch: eventsRefetch, isRefetching: eventsIsRefetching, isLoading: eventsIsLoading } = useEventList( { postBody: reqBody, enabled: parentType !== 'nocodeEventsList' } )
  const { data: nocodeEventsListData, refetch: nocodeEventsRefetch, isRefetching: nocodeEventsIsRefetching, isLoading: nocodeEventsIsLoading } = useNocodeEventList( { postBody: reqBody, enabled: parentType === 'nocodeEventsList'} )
  
  const data = useMemo( () => {
    if ( parentType === 'nocodeEventsList' && noCodeEventsFeatureFlag ) {
      return nocodeEventsListData?.data?.data
    }
    return eventsListData?.data?.data
  }, [ parentType, eventsListData, nocodeEventsListData, noCodeEventsFeatureFlag ] )

  const setSortByVal = (newSort) => {
    const {id, desc} = newSort()[0];
    const isCustomUserProperty = userProperties.includes(removeUxCamCustomProperty(id));
    const isCustomEventProperty = eventProperties.includes(removeUxCamCustomProperty(id));
    const sortByVal = [{
      id,
      desc,
      ...isCustomUserProperty && { isCustomUserProperty },
      ...isCustomEventProperty && { isCustomEventProperty },
    }]
    setOrderBy(sortByVal);
  }

  const multiScreenSkippedData = useScreenSkippedData();
  const session = useMemo(
    () =>
      data?.body
        ?.filter((el) => {
          if (el.sessionid === sessionid) {
            return el.userProperty;
          }
          return null;
        })
        .filter((el) => el)[0],
    [data, sessionid]
  );
  const handleSortByOrder = async (order) => {
    const sortedBody = {
      appid,
      date_range: dateSegment,
      filters: eventSegment,
      table: 'eventTable',
      orderBy: order,
      page: 1,
      webApp: isWebApp,
    };
    getEventSortedItems(sortedBody).then(() => {
      if ( parentType === 'nocodeEventsList' ) {
        nocodeEventsRefetch()
      } else eventsRefetch()
    });
  };
  const saveDetailSize = (key, value) =>
    dispatch(setEventDetailSizeByKey(key, value));
  const toggleFullScreen = useCallback(() => {
    const container = fullScreenContainerRef.current;
    const isFullScreen = document.webkitCurrentFullScreenElement;
    const isFireFoxFullScreen = document.mozFullScreenElement;
    if (container) {
      if (isFullScreen) {
        document.webkitExitFullscreen && document.webkitExitFullscreen();
      } else {
        container.webkitRequestFullscreen &&
          container.webkitRequestFullscreen();
      }
      if (isFireFoxFullScreen) {
        document.mozCancelFullScreen && document.mozCancelFullScreen();
      } else {
        container.mozRequestFullScreen && container.mozRequestFullScreen();
      }
    }
  }, []);
  const callRedirectPage = () => {
    reqBody.page = 1
    if ( parentType === 'nocodeEventsList' ) {
      nocodeEventsRefetch()
    } else eventsRefetch()

    goToPage({
      page: 1,
      appId: appid,
      sessionid,
      autoplay,
      segment: eventSegment,
      parentType,
      eventid,
      starttime,
      expanded: sessionid || false,
    });
  }
  useEffect(() => {
    if(!isMounted) return
    if(sessionid) {
        goToPage({
          page: eventpage,
          appId: appid,
          sessionid,
          autoplay,
          segment: eventSegment,
          parentType,
          eventid,
          starttime,
          expanded: sessionid || false,
          dateSegment
      });
    } else callRedirectPage()
  }, [dateSegment?.value, eventSegment])

  useEffect(() => {
    if (orderBy?.length && orderBy[0]?.sortName !== '') {
      callRedirectPage();
      const sortByVal = [{
        sortName: orderBy[0]?.id,
        sortOrder: orderBy[0]?.desc ? 'desc' : 'asc',
        ...orderBy[0].isCustomUserProperty && { isCustomUserProperty: orderBy[0].isCustomUserProperty },
        ...orderBy[0].isCustomEventProperty && { isCustomEventProperty: orderBy[0].isCustomEventProperty }
      }]
      handleSortByOrder(sortByVal);
    }
  }, [orderBy]);

  useEffect(() => {
    componentMountToggler(true);
    return () => {
      componentMountToggler(false);
    };
  }, []);

  const sortByTransform = (sort) => {
    if (sort.length > 0) {
      const { sortName, sortOrder, isCustomUserProperty } = sort[0];
      return [{
        id: sortName,
        desc: sortOrder === 'desc',
        ...isCustomUserProperty && { isCustomUserProperty },
      }]
    }
    return []
  }

  return (
    <Wrapper expanded={Boolean(sessionid) || false}>
      <EventToolbar
        expanded={Boolean(!sessionid) || false}
        session={session}
        containerRef={fullScreenContainerRef}
        eventsList={data}
      />
      <Main ref={fullScreenContainerRef}>
        <>
          <ResizePanel
            direction="e"
            handleClass="resize-handle"
            containerClass="resize-panel-container"
            borderClass="resize-border"
            initialWidth={
              parseInt(resizeWidth?.initial) > 518
                ? 518
                : resizeWidth?.initial < 220
                ? 220
                : resizeWidth?.initial
            }
            saveDetailSize={saveDetailSize}
          >
            <TableBox>
              <EventList
                data={data || {}}
                isLoading={ eventsIsRefetching || eventsIsLoading || nocodeEventsIsLoading || nocodeEventsIsRefetching } 
                setSortedBy={setSortByVal}
                sortedBy={
                  orderBy?.length > 0
                    ? orderBy
                    : sortByTransform(data?.orderBy || [])
                }
              />
            </TableBox>
          </ResizePanel>
          {sessionid && (
            <>
              <Box aria-label="video" className='middle-panel'>
                <SessionDetails
                  sessionList={data}
                  appId={appid}
                  sessionId={sessionid}
                  uploadedOn={session?.sessionUploadedDateTime}
                  userId={session?.uxcamuserid}
                  toggleFullScreen={toggleFullScreen}
                  multiScreenSkippedData={multiScreenSkippedData}
                  setDetailErrorMessage={() => null} // we will update this when we remove graph api call in event list
                />
              </Box>
              <ResizePanel
                direction="w"
                handleClass="resize-handle"
                containerClass="resize-panel-container-second"
                borderClass="resize-border"
                initialWidth={
                  parseInt(resizeWidth?.end) > 548 ? 548 : resizeWidth?.end
                }
                saveDetailSize={saveDetailSize}
              >
                <Box>
                  <SessionDetailSideBar
                    multiScreenSkippedData={multiScreenSkippedData}
                    uploadedOn={session?.sessionUploadedDateTime}
                  />
                </Box>
              </ResizePanel>
            </>
          )}
        </>
      </Main>
    </Wrapper>
  );
};

export default memo(EventDetailsAndVideo);
