import React, { useEffect, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { findLastIndex, clone } from 'underscore';
import styled from 'styled-components';
import { clearEventStatsData } from 'redux/actions/statistic';
import {
  changeCommonValue,
  fetchPlanHatApi,
} from 'redux/actions/common';
import {
  getEventName,
  updateSelectedEvent,
} from 'redux/actions/event';
import { handleValuesByName } from 'redux/actions/sessionStatistics';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { useRestrictionContext } from "components/IntegratePages/layout/context/restrictionContext"
import { useIsAppType } from 'hooks/useIsAppType';
import Statistics from './Statistics/index';
import composedEventsHoc from './hoc';
import EventDetailsAndVideo from './EventDetailsAndVideo';
import EventsPageLocked from './EventsPageLocked';
import { useNoCodeEventsContext } from '../sessions/Context/NoCodeEventsContext';

const ContentContainer = styled.div`
  height: 100%;
  padding-top:  ${ ( { noPadding } ) => noPadding ? '0px' : '60px' };
  pointer-events:  ${( {isGlobalFilterVisible}) => isGlobalFilterVisible ?  `none` : ''};
`;

const EventPage = (props) => {
  const { callApi, callGraphApi } = props;
  const isWebApp = useIsAppType( 'web' );
  const dispatch = useDispatch();
  const {
    urlReducer: { parentType, appId },
    appFilter: {
      dateSegment,
      event: { segment: filters },
    },
  } = useSelector((state) => state);
  const { showEventsPageLockScreen } = useRestrictionContext()
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()

  const { megaDropdownVisible, megaBottomDropdownVisible } = useSelector(
    (state) => state.megaFilterReducer
  )

  const isGlobalFilterVisible = useMemo(() => megaDropdownVisible || megaBottomDropdownVisible, [megaDropdownVisible, megaBottomDropdownVisible])

  const clonedEventSegment = clone(filters);

  const {
    table: eventNameDropdownList,
  } = useSelector(({ eventTable }) => eventTable);


  const eventNameReq = useMemo(() => ({
    appid: appId,
    date_range: dateSegment,
    filters: [],
  }), [appId, dateSegment]);

  const eventPropsReqBody = useMemo(() => {
    const eventPropertyFilter = clonedEventSegment?.filter(
      (segment) => segment.attribute === 'event_name'
    );
    return {
      attribute: 'event_custom_property',
      filter: clonedEventSegment?.length > 0 ? eventPropertyFilter : [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    };
  }, [clonedEventSegment, dateSegment]);

  const userPropsReqBody = useMemo(
    () => ({
      attribute: 'user_custom_property',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment]
  );

  const customScreenPropsReqBody = useMemo(
    () => ({
      attribute: 'session_screen_with_property',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment]
  );

  const handleResetFetch = async () => {
    dispatch(clearEventStatsData())
    dispatch(
      handleValuesByName({
        dropName: 'eventPropertyFilter',
        data: [],
      })
    )
  }

  const callEventProperties = async() => {
    dispatch(changeCommonValue('eventProperty_Ldr', true));
    dispatch( getFilterPropertyRemoteData( eventPropsReqBody, false, true ) ).finally(() => dispatch(changeCommonValue('eventProperty_Ldr', false)))
  }

  const callUserProperties = async() => {
    dispatch(changeCommonValue('userProperty_Ldr', true));
    dispatch(getFilterPropertyRemoteData(userPropsReqBody, false, true)).finally(() => dispatch(changeCommonValue('userProperty_Ldr', false)) );
  }

  const callCustomScreenProperties = async() => {
    dispatch(getFilterPropertyRemoteData(customScreenPropsReqBody, false, true)).finally(() => dispatch(changeCommonValue('customScreenProperty_Ldr', false)) );
  }

  const callAfterResetApi = async () => {
    await handleResetFetch()
    dispatch(updateSelectedEvent([]));
    callApi(appId, 'initial', undefined, isWebApp);
    dispatch(getEventName(eventNameReq));
    if ( parentType === 'eventsList' || parentType === 'statistics') {
      await callEventProperties();
    }
    callUserProperties();
    callCustomScreenProperties();
    if (parentType === 'eventsList') dispatch(
      fetchPlanHatApi({
        action: 'events list page',
      })
    );
    if (parentType === 'nocodeEventsList') dispatch(
      fetchPlanHatApi({
        action: 'nocode events list page',
      })
    );
  };

  const updateEventFromUrl = () => {
    if (clonedEventSegment?.length) {
      const indexBy = findLastIndex(clonedEventSegment, {
        attribute: 'event_name',
      });
      if (indexBy > -1 && eventNameDropdownList?.length) {
        const keyObj = clonedEventSegment[indexBy];
        dispatch(updateSelectedEvent(keyObj.value));
      }
    }
  };
  useEffect(() => {
    updateEventFromUrl();
  }, [eventNameDropdownList]);

  useEffect(() => {
    if (parentType === 'eventsList' || parentType === 'nocodeEventsList' || parentType === 'statistics') callAfterResetApi();
  }, [appId, isWebApp]);

  if ( showEventsPageLockScreen ) {
    return <EventsPageLocked />
  }

  let Component = <></>;

  if (parentType === 'eventsList' || ( parentType === 'nocodeEventsList' && noCodeEventsFeatureFlag ))
    Component = <EventDetailsAndVideo />
  if (parentType === 'statistics') {
    Component = (
      <Statistics callGraphApi={callGraphApi} />
    );
  }
  
  return (
    <ContentContainer
      noPadding={ showEventsPageLockScreen }
      isGlobalFilterVisible={isGlobalFilterVisible}
    >
      {Component}
    </ContentContainer>
  )
};

export default composedEventsHoc(EventPage);
