import React, { useState, memo, useEffect, useMemo } from 'react';
import Router from 'next/router';
import dynamic from 'next/dynamic';

import styled from 'styled-components';
import { useSelector } from 'react-redux';
import { Button, Dropdown, Tooltip } from 'antd';

import LoaderInfo from 'Utils/helpers/LoaderInfo';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';

import LoaderAdvanced from 'components/common/LoaderAdvanced';
import { ArrowLeftIconSvg, CloseIcon, ColumnIconSVG } from 'components/svg_files';
import ShareSessionModal from 'components/shared/Sessions/SharedSession/ShareSessionModal';
import SessionOption from 'components/features/sessions/SessionDetailsAndVideo/Toolbar/SessionOption';
import EventsDownloadCSV from 'components/shared/ExportCSV/Download';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';


const ToolbarWrapper = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 5px 16px 10px;
  z-index: 1;
  position: relative;

  .dropdown-btn {
    padding: 0;
    display: flex;
    justify-content: center;
    align-content: center;
    height: fit-content;
    padding: 6px 10px;
    height: 32px;
    border-radius: 4px;
    border-color: #828282;
    margin-left: 20px;
    background-color: #ffffff;

    svg {
      path,
      rect {
        fill: #828282;
        stroke: #828282;
      }
    }
    &:hover{
      background:transparent;
      svg{
        path,rect{
          fill: #5D97FF;
          stroke: #5D97FF;
        }
      }
    }
  }

  .btn-quick-filter {
    button {
      height: 32px;
      border-radius: 4px;
      border-color: #5D97FF;
      color: #5D97FF;
      background-color: #ffffff;
      letter-spacing: 0.4px;
      &:hover{
        background:transparent;
        color: #5D97FF;
        svg{
          path{
            fill:#5D97FF;
          }
        }
      }
    }
  }
`;

const ToolbarLeft = styled.div`
  font-size: ${({ smaller }) => (smaller ? '0.875rem' : '1.125rem')};
  /* transition: font-size 0.4s ease-in-out;
  transition-delay: 400ms; */
  display: flex;
  align-items: center;
`;

const EventButton = styled.button`
  font-weight: ${props => props?.expanded ? '500' : '400'};
  font-size: ${props => props?.expanded ? '18px' : '14px'};
  line-height: ${props => props?.expanded ? '21px' : '16.41px'};
  cursor: ${props => !props?.expanded ?'pointer' : 'auto'};
  background-color: transparent;
  border: ${props=> props?.expanded ? 'none' : '1.16667px solid rgba(37, 56, 88, 0.6)'};
  box-sizing: border-box;
  border-radius: 4px;
  height: 32px;
    &:hover {
    border-color:${props => !props?.expanded ? '#5D97FF' : '' };
    color:${props => !props?.expanded ? '#5D97FF' : '' } ;
  }
  svg {
  margin-right: 3px;
  margin-left: 2px;
  }
`;

const ToolbarRight = styled.div`
  display: flex;
  align-items: center;
  .ant-dropdown-trigger{
    background:#ffffff;
    &:hover{
      background:transparent;
      border-color: #C0CAD9 !important;
      svg{
        path{
          fill:#5D97FF;
        }
      }
    }
  }
`;

const StyleCloseButton = styled(Button)`
    background: #ffffff;
    border: 0px;
    padding: 0px;
    margin-left: 15px;
    &:hover{
      background: transparent;
      color: #5D97FF;
      svg{
        path{
          fill:#5D97FF;
        }
      }
    }
`

  const ColumnUpdate = dynamic(import("components/common/ColumnUpdate"));

const EventToolbar = ({ expanded, session, containerRef, eventsList }) => {
  const [dropdownVisible, setDropdownVisibility] = useState(false);
  const [cachedSession, setCachedSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const {
    urlReducer: urlQuery,
    currentAppReducer,
    appFilter,
  } = useSelector((state) => state);
  const { _id: appid } = currentAppReducer;
  const { eventpage, sessionid, autoplay, parentType } = urlQuery;

  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()

  const addCustomEventPropsEnabled = useMemo( () =>  parentType !== 'nocodeEventsList', [ parentType ] )

  const eventSegment = appFilter?.event?.segment;
  const headers = useMemo(() => eventsList?.header?.filter((item) => item.attribute !== 'country' && item.attribute !== 'trackedon' && item.attribute !== 'video'), [eventsList?.header])

  const handleEventClick = () => {
    const segment = eventSegment;
    const newPageType = parentType === 'eventsList' ? 'events' : 'smart-events'
    const newParentType = parentType === 'nocodeEventsList' ? 'nocodeEventsList' : 'eventsList'
    const autoPlayPart = `&autoplay=${autoplay ? '1' : ' 0'}`;
    const url = urlSegmentEncoder(
      `/app/${appid}/${ newPageType }/list/${eventpage}?`,
      segment
    );
    const query = `appId=${appid}&parentType=${ newParentType }&eventpage=${eventpage}&starttime=0${autoPlayPart}`;
    Router.push(`/integration?${query}`, url);
  };

  const handleVisibleChange = (flag) => setDropdownVisibility(flag);
  const setLoader = (value) => setLoading(value);
  const pageTitle = useMemo( () => `${ noCodeEventsFeatureFlag ? parentType === 'nocodeEventsList' ? 'Smart' : 'Coded' : 'Custom' } events` , [ parentType, noCodeEventsFeatureFlag ] )

  useEffect(() => {
    if (session && session !== cachedSession) setCachedSession(session);
  }, [session]);

  return (
    <ToolbarWrapper>
      <ToolbarLeft smaller={Boolean(sessionid)}>
        <EventButton expanded={expanded} type="button" onMouseDown={handleEventClick}>
          { expanded ? pageTitle : <><ArrowLeftIconSvg /> { pageTitle } list </> }
        </EventButton>
      </ToolbarLeft>
      <ToolbarRight>
        {expanded ? (
          <>
            <Dropdown
              overlayClassName='column-edit-dropdown'
              className="dropdown-btn"
              trigger={['click']}
              onVisibleChange={handleVisibleChange}
              visible={dropdownVisible}
              overlay={
                <LoaderAdvanced
                  show={loading}
                  message={<LoaderInfo />}
                  backgroundStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.0)' }}
                >
                  <ColumnUpdate
                     type={ parentType === 'nocodeEventsList' ? 'nocodeEvent' : 'event' }
                     appid={appid}
                     setLoading={setLoader}
                     dropdownVisible={dropdownVisible}
                     setDropdownVisibility={setDropdownVisibility}
                     headers={headers}
                     showAddCustomUserButton
                     showAddCustomEventButton={addCustomEventPropsEnabled}
                     />
                </LoaderAdvanced>
              }
            >
              <Button>
                <ColumnIconSVG />
              </Button>
            </Dropdown>
            <EventsDownloadCSV/>
          </>
        ) : (
          <>
            <ShareSessionModal />
            <SessionOption containerRef={containerRef} />
            <Tooltip overlayClassName='custom-popover' title='Close'>
            <StyleCloseButton icon={<CloseIcon/>} onMouseDown={handleEventClick}/>
            </Tooltip>
          </>
        )}
      </ToolbarRight>
    </ToolbarWrapper>
  );
};

export default memo(EventToolbar);
