import React from 'react';
import { Menu, Dropdown } from 'antd';
import { map } from 'lodash';
import { DownOutlined } from '@ant-design/icons';
import CategoryLevelDropdown from 'components/common/CategoryLevelDropdown';

const { SubMenu, Item } = Menu;
const obj = {
  count: 'Count',
  sum: 'Sum',
  max: 'Maximum',
  min: 'Minimum',
  avg: 'Average',
};
const displayObj = {
  events: 'Count of events',
  'users with events': 'Count of user with events',
  'sessions with events': 'Count of sessions with events',
};
const AggregationDropdown = (props) => {
  const [visible, setDropdownVisible] = React.useState(false);
  const { selectedOption } = props;
  let tooltipTitle = selectedOption?.operator
    ? `${obj[selectedOption.operator]} of ${
        selectedOption.json_field &&
        (selectedOption.json_field.length
          ? `event property`
          : selectedOption.display)
      }`
    : selectedOption?.display;
  tooltipTitle = Object.keys(displayObj).includes(tooltipTitle)
    ? displayObj[tooltipTitle]
    : tooltipTitle;
  if (selectedOption?.json_field && selectedOption.json_field.length) {
    tooltipTitle = (
      <>
        {tooltipTitle} <em>{selectedOption.display}</em>
      </>
    );
  }
  return (
    <Dropdown
      trigger={['click']}
      overlay={
        <MenuItem
          setDropdownVisible={setDropdownVisible}
          isDropdownVisible={visible}
          {...props}
        />
      }
      visible={visible}
      onVisibleChange={(flag) => setDropdownVisible(flag)}
    >
      <a
        href="#!"
        className="ant-dropdown-link"
        onClick={(e) => {
          e.preventDefault();
          setDropdownVisible(true);
        }}
      >
        {tooltipTitle}{' '}
        <span><DownOutlined className='sm-caret-down' /></span>
      </a>
    </Dropdown>
  );
};
export default AggregationDropdown;
const MenuItem = ({
  options_operator,
  options_aggregation,
  handleEvent,
  selectedOption,
  setDropdownVisible,
  isDropdownVisible,
}) => {
  const [hoverValue_propertyValue, handlePropertyValue] = React.useState(null);
  const [hoverValue_subMenu, handleHoverValue] = React.useState(null);
  const [hoveredValue, setHoveredValue] = React.useState(null);
  if (options_operator) {
    delete options_operator.json.std;
  }
  let { operator } = selectedOption;
  if (operator === '') {
    operator = 'count';
  }
  React.useEffect(() => {
    !isDropdownVisible && handleHoverValue(false);
    return () => {
      handleHoverValue(false);
      handlePropertyValue(null);
      setHoveredValue(null);
    };
  }, [isDropdownVisible]);
  return options_operator ? (
    <Menu
      className="dropdown-multilevel"
      defaultOpenKeys={['count']}
      selectedKeys={operator === 'json' ? [] : [selectedOption.attribute]}
      onClick={async (e) => {
        setDropdownVisible(false);
        setHoveredValue(null);
        await handleEvent(e);
      }}
      mode="vertical"
    >
      {isDropdownVisible &&
        map(options_operator, (value, key) => {
          let arrayValue = [];
          if (key === 'json') {
            map(value, (v, k) => {
              arrayValue.push({
                display: v.display,
                attribute: k,
              });
            });
            const lastItem = [arrayValue.pop()];
            arrayValue = [...lastItem, ...arrayValue];
          }
          return (
            key === 'json' &&
            map(arrayValue, (v, k) => {
              k = v.attribute;
              const title =
                v.display === 'Sample Count'
                  ? `Count of ...`
                  : `${v.display} of ...`;
              // title = operator === k ? tooltipTitle : title
              const activeClass =
                operator === k
                  ? selectedOption.json_field
                    ? 'agg-sub-selected-option'
                    : 'agg-selected-option'
                  : '';
              return (
                <SubMenu
                  key={k}
                  value={k}
                  title={title}
                  className={`sub-multilevel ${activeClass}`}
                  popupClassName={`sub-multilevel ${activeClass}`}
                  onTitleMouseEnter={(e) => {
                    setHoveredValue(e.key);
                    e.key === k
                      ? handleHoverValue(true)
                      : handleHoverValue(false);
                  }}
                >
                  {hoveredValue === k && hoverValue_subMenu && (
                    <Item disabled className="menu-title">
                      {k === 'count'
                        ? `Choose what to count`
                        : `Choose ${
                            hoverValue_propertyValue || 'event property'
                          } to ${v.display.toLowerCase()}`}
                    </Item>
                  )}
                  {hoveredValue === k &&
                    k === 'count' &&
                    map(options_aggregation, (x) => (
                      <Item key={x.attribute}>{x.display}</Item>
                    ))}
                  {hoveredValue === k && k === 'count' && (
                    <SubMenu
                      key="event_property"
                      title="events with property"
                      className="aggregation-property-sub-menu"
                    >
                      <Item disabled className="menu-title">{`Choose ${
                        hoverValue_propertyValue || 'event property'
                      } to count`}</Item>
                      <EventPropertyDropdown
                        operator={k}
                        handleEvent={handleEvent}
                        selectedOption={operator === k && selectedOption}
                        aggregationEventId="event_property"
                        handlePropertyValue={handlePropertyValue}
                        setDropdownVisible={setDropdownVisible}
                        isDropdownVisible={isDropdownVisible}
                        setHoveredValue={setHoveredValue}
                      />
                    </SubMenu>
                  )}
                  {hoveredValue === k && k !== 'count' && (
                    <EventPropertyDropdown
                      operator={k}
                      handleEvent={handleEvent}
                      selectedOption={operator === k && selectedOption}
                      _id={k}
                      handlePropertyValue={handlePropertyValue}
                      setDropdownVisible={setDropdownVisible}
                      isDropdownVisible={
                        hoveredValue === k && hoverValue_subMenu
                      }
                      handleHoverValue={handleHoverValue}
                      setHoveredValue={setHoveredValue}
                    />
                  )}
                </SubMenu>
              );
            })
          );
        })}
    </Menu>
  ) : null;
};
const EventPropertyDropdown = ({
  handleEvent,
  operator,
  selectedOption,
  handlePropertyValue,
  setDropdownVisible,
  isDropdownVisible,
  handleHoverValue,
  setHoveredValue,
  aggregationEventId
}) => (
  <CategoryLevelDropdown
    aggregationEventId={aggregationEventId}
    handleChangeEvents={handleEvent}
    id="events_agg_dropdown"
    isImprovedAggregation
    eventProperty
    placeholderText="Add Aggregation"
    userPropertyFromStats={false}
    _operator={operator}
    eventDropVal={selectedOption}
    key={operator}
    handleHoverPropertyValue={handlePropertyValue}
    setDropdownVisible={setDropdownVisible}
    isStatisticsDropdownVisible={isDropdownVisible}
    handleHoverValue={handleHoverValue}
    setHoveredValue={setHoveredValue}
  />
);
