/* eslint-disable no-nested-ternary */
import React, { createRef, memo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { map, reject, findLastIndex, each, clone } from 'lodash';
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import ReactLoader from 'components/common/reactLoading'
import { handleValuesByName } from 'redux/actions/statistic';
import { fetchPlanHatApi } from 'redux/actions/common';
import GraphTypeDropdown from 'components/common/Customary/GraphTypeDropdown';
import { graphTypeObj } from 'components/common/Customary/graphType';
import Wrapper from 'components/common/Customary/Wrapper';
import CategoryLevelDropdown from 'components/common/CategoryLevelDropdown';
import StatisticsGraphV2 from 'components/common/StatisticsGraph';
import CustomExportGraphDropdown from 'Utils//helpers/CustomExportGraphDropdown';
import PendingLoaderInfo from 'components/common/PendingLoaderInfo';
import { trackPageViews } from 'redux/actions/trackingReport';
import { getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils';
import { useIsAppType } from 'hooks/useIsAppType';
import { getRestructedUTMData } from 'components/common/Analytics/Statistics';
import { findCategoryTitle } from 'Utils/helpers/commonUtils';
import AggregationDropdown from './AggregationDropdown';

const aggregationDropdown = [
  {
    attribute: 'event_count',
    display: 'events',
    type: 'count',
    table: 'event',
  },
  {
    attribute: 'event_unique_user_count',
    display: 'users with events',
    type: 'count',
    table: 'event',
  },
  {
    attribute: 'event_unique_session_count',
    display: 'sessions with events',
    type: 'count',
    table: 'event',
  },
];
const insideLoader = (
  <>
    <PendingLoaderInfo preText="Computing chart data" />
    <ReactLoader />
  </>
);
const mappedObj = {
  type: { event_count: 'count', event_custom_property: 'json', user_custom_property: 'json' },
  table: 'event',
};
const chartRef = createRef();
const Statistics = memo(({ callGraphApi }) => {
  const dispatch = useDispatch();
  const {
    statisticsReducer: {
      dropdownData,
      eventDropValues,
      grpByVal,
      loader,
      graphSelectedVal,
      graphData,
    },
    commonReducer: { bottomBarClassFlag },
    appFilter: { fetchProperty = {}, dateSegment },
  } = useSelector((state) => state);
  const [isEventProperty, toggleIsEventProperty] = React.useState(false);
  const isWebSdk = useIsAppType('web');
  const userProperty = fetchProperty?.custom_user_property?.data || [];
  const eventProperty = fetchProperty?.custom_event_property?.data || [];
  const userFirstUtm = fetchProperty?.user_first_utm?.data || [];
  const aggOperators = dropdownData?.agg_operators;
  let groupbyDropdown = dropdownData && clone(dropdownData.groupby_dropdown);
  const extra = {
    'Custom event properties': eventProperty || [],
    'Custom user properties': userProperty || [],
  };
  groupbyDropdown = { ...groupbyDropdown, ...extra };
  const restructuredUTMData = getRestructedUTMData(userFirstUtm);
  if (dropdownData && dropdownData.groupby_dropdown && isWebSdk) {
    dropdownData.groupby_dropdown['Initial landing UTM'] = restructuredUTMData;
  }
  const graphTypeVal = graphSelectedVal && graphSelectedVal.key;
  const removeValue = (array, id) =>
    reject(
      array,
      (item, index) => index === id // or some complex logic
    );
  const delGrpByArr = async (index) => {
    const grpByValDuplicate = removeValue(grpByVal, index);
    const payload = {
      dropName: 'grpByVal',
      data: [...grpByValDuplicate],
    };
    await dispatch(handleValuesByName(payload));
    callGraphApi(null, null, grpByValDuplicate, null);
  };
  const handleChartChange = async (val) => {
    const payload = {
      dropName: 'graphSelectedVal',
      data: graphTypeObj[val],
    };
    await dispatch(handleValuesByName(payload));
    callGraphApi(null, null, grpByVal, true);
    dispatch(
      fetchPlanHatApi({
        action: 'Graph type changed',
        info: {
          page: 'Event Analytics',
          'graph type': val,
        },
      })
    );
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_change_chart_type',
        track_type: 'event',
        eventProperty: {
          chart_type: val
        },
      })
    );
  };
  const handleAggOperators = async (val) => {
    eventDropValues.operator = val;
    const payload = {
      dropName: 'eventDropValues',
      data: eventDropValues,
    };
    await dispatch(handleValuesByName(payload));
    if (val) {
      await callGraphApi(null, null, grpByVal, null);
    }
  };
  const handleEvent = async (
    val,
    _idByArr,
    index,
    isKeyPress,
    isUserProperty,
    operator
  ) => {
    eventDropValues.operator = val['keyPath'][1];
    const payloadOperator = {
      dropName: 'eventDropValues',
      data: eventDropValues,
    };
    await dispatch(handleValuesByName(payloadOperator));
    const keyPressValue = isKeyPress && val;
    let property;
    const value = keyPressValue || (typeof val === 'object' ? val.key : val);
    const attrArr = aggregationDropdown.map((v) => v.attribute);
    const indexOf = findLastIndex(aggregationDropdown, {
      attribute: value,
    });
    const displayMapped =
      indexOf >= 0 &&
      aggregationDropdown[indexOf] &&
      aggregationDropdown[indexOf]['display'];
    const containsAttr = attrArr.includes(value);
    if (!containsAttr) {
      property = isKeyPress
        ? isUserProperty
          ? 'user_custom_property'
          : 'event_custom_property'
        : val.item.props.property;
    }
    const payload = {
      dropName: 'eventDropValues',
      data: {
        attribute: containsAttr ? value : property,
        type: containsAttr
          ? mappedObj['type'][value]
          : mappedObj['type'][property],
        table: property === 'user_custom_property' ? 'appuser' : 'event',
        operator:
          operator ||
          (property === 'event_custom_property' || property === 'user_custom_property'
            ? 'count'
            : ''),
        json_field: !containsAttr ? [value] : undefined,
        display: property ? value : displayMapped,
      },
    };
    toggleIsEventProperty(attrArr.includes(value));
    await dispatch(handleValuesByName(payload));
    callGraphApi(null, null, grpByVal, null);
    dispatch(
      fetchPlanHatApi({
        action: 'Aggregation function changed',
        info: {
          'function name': containsAttr ? value : property,
        },
      })
    );
  };

  const handleGrpBy = async (
    val,
    _idByArr,
    index,
    isKeyPress,
    isUserProperty
  ) => {
    const keyPressValue = isKeyPress && val;
    let truePayloadObj;
    let categorytitle;
    let newGrpArr;
    let property;
    const dataValue = keyPressValue || val.key;
    const obj = {};
    const grpByArr = [...grpByVal];
    let eventDisplay = '';
    let newPData;
    await each(groupbyDropdown, (_v) => {
      _v.map((value) => {
        obj.values = {
          ...obj.values,
          [value.attribute]: value.table,
        };
      });
    });
    if (!Object.keys(obj.values).includes(dataValue))
      eventDisplay = `${isUserProperty ? 'User': 'Event'} property`;
    const isInitialLandingUTM = findCategoryTitle(dataValue, groupbyDropdown) === 'Initial landing UTM'
    if ( isInitialLandingUTM ){
      truePayloadObj = {
        attribute: 'user_first_utm',
        table: 'appuser',
        type: 'json',
        display: dataValue,
        json_field: [dataValue],
      }
    } else if (!eventDisplay) {
      categorytitle = val.item.props.categorytitle;
      const indexOf = findLastIndex(groupbyDropdown[categorytitle], {
        display: val.item.props.display,
      });
      newPData = groupbyDropdown[categorytitle][indexOf];
      truePayloadObj = newPData;
      if (['event_period_day', 'event_date_week', 'event_date_month'].includes(dataValue)) truePayloadObj.time_zone_offset =  getTimezoneOffset(dateSegment.tz, new Date() )
    } else {
      property = isKeyPress
        ? isUserProperty
          ? 'user_custom_property'
          : 'event_custom_property'
        : val.item.props.property;
      const attribute =
        property === 'eventpropertyvalueofgrp'
          ? 'event_custom_property'
          : property === 'userpropertyvalueofgrp'
          ? 'user_custom_property'
          : property === 'utmpropertyvalueofgrp'
          ? 'utm' 
          :property;
      truePayloadObj = {
        attribute,
        table: property === 'user_custom_property' ||  property === 'userpropertyvalueofgrp' ? 'appuser' :
        property === 'utmpropertyvalueofgrp' ? 'session' :
        'event',
        type: 'json',
        // display: eventDisplay,
        json_field: eventDisplay ? [dataValue] : undefined,
      };
    }
    if (val?.item?.props?.max_group_number)
      truePayloadObj['max_group_number'] = val.item.props.max_group_number;
    if (val?.item?.props?.labels?.length)
      truePayloadObj['labels'] = val.item.props.labels;
    else truePayloadObj['labels'] = undefined;
    if (_idByArr === 'grp-array' && index >= 0 && index < 2) {
      grpByArr[index] = truePayloadObj;
      newGrpArr = [...grpByArr];
    }
    if (_idByArr === 'grp-main' && grpByArr.length < 2)
      newGrpArr = [...grpByArr, truePayloadObj];
    const payload = {
      dropName: 'grpByVal',
      data: newGrpArr,
    };
    await dispatch(handleValuesByName(payload));
    if (
      newPData &&
      newPData.attribute === 'event_period_day' &&
      graphSelectedVal.type === 'pie'
    ) {
      const graphPayload = {
        dropName: 'graphSelectedVal',
        data: {},
      };
      await dispatch(handleValuesByName(graphPayload));
    }
    callGraphApi(null, null, newGrpArr, null);
    dispatch(
      fetchPlanHatApi({
        action: `Changed event analytics grouping ${index + 1}`,
        info: {
          'Grouping type': dataValue,
          page: 'event analytics',
        },
      })
    );
  };
  React.useEffect(() => {
    dispatch(fetchPlanHatApi({ action: 'Entered event analytics' }));
  }, []);
  return (
    <div className="event-big-box-analytics">
      <div className="stat-full-box">
        <div className="stat-graph-box">
          <div className="stat-filter-bar">
            <div className="filter-left-box">
              <div className="dropdown-wrapper">
                <div className="big-combo-box">
                  <Wrapper isEventProperty={isEventProperty} dataIntercomTarget="Count">
                    <AggregationDropdown
                      handleAggOperators={handleAggOperators}
                      selectedOption={eventDropValues}
                      options_operator={aggOperators}
                      key="agg-dropdown-improved"
                      options_aggregation={aggregationDropdown}
                      handleEvent={handleEvent}
                    />
                  </Wrapper>
                  {grpByVal?.length &&
                    map(grpByVal, (value, key) => (
                      <Wrapper
                        label={key === 0 ? 'grouped by' : 'and'}
                        key={value.attribute.includes('property') ? value.json_field[0] : value.attribute}
                        _idByArr="grp-array"
                        filterArr={delGrpByArr}
                        _grpByArr={grpByVal}
                        _index={key}
                        isRevamped
                        dataIntercomTarget={key === 0 ? 'grouped by' : 'and'}
                      >
                        <CategoryLevelDropdown
                          key={value.attribute.includes('property') ? value.json_field[0] : value.attribute}
                          handleChangeEvents={handleGrpBy}
                          handleValuesByName={handleValuesByName}
                          id="groupby_dropdown"
                          options={groupbyDropdown}
                          eventDropVal={value}
                          _idByArr="grp-array"
                          group_list={grpByVal}
                          indexByGrpby={key}
                          // userPropertyFromStats
                          isRevamped
                          isEventAnalytics
                          eventProperty
                        />
                      </Wrapper>
                    ))}
                </div>
              </div>
              {grpByVal?.length < 2 ? (
                <Wrapper className="add-btn">
                  <CategoryLevelDropdown
                    key={grpByVal[0].attribute.includes('property') ? grpByVal[0].json_field[0] : grpByVal[0].attribute}
                    handleChangeEvents={handleGrpBy}
                    handleValuesByName={handleValuesByName}
                    id="groupby_dropdown"
                    options={groupbyDropdown}
                    _idByArr="grp-main"
                    placeholderText="+ add grouping"
                    indexByGrpby={1}
                    group_list={grpByVal}
                    // userPropertyFromStats
                    isRevamped
                    isEventAnalytics
                    eventProperty
                  />
                </Wrapper>
              ) : null}
            </div>
            <div className="filter-right-box">
              <Wrapper>
                <CustomExportGraphDropdown chartRef={chartRef} graphData={graphData} />
              </Wrapper>
              <Wrapper>
                <GraphTypeDropdown
                  handleChartChange={handleChartChange}
                  graphTypeVal={graphTypeVal}
                  graphTypeObj={graphTypeObj}
                  graphData={graphData}
                  group_list={grpByVal}
                />
              </Wrapper>
            </div>
          </div>
          <LoaderAdvanced
            show={loader || false}
            message={insideLoader}
            backgroundStyle={{
              backgroundColor: 'rgba(255,255,255,0.6)',
            }}
            style={{ height: '100%' }}
          >
            <StatisticsGraphV2
              graphData={graphData}
              eventDropVal={eventDropValues}
              height="100%"
              chartRef={chartRef}
            />
          </LoaderAdvanced>
        </div>
      </div>
    </div>
  );
});
export default Statistics;
